export function ComponentContract({
  componentName = "{{componentName}}",
  requiredProp = "{{requiredProp}}",
  satisfied = {{satisfied}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 12, marginBottom: 14 }}>
        <tbody>
          <tr><th style={{ textAlign: "left", padding: "5px 6px" }}>{componentName} contract</th><th style={{ textAlign: "left", padding: "5px 6px" }}>status</th></tr>
          <tr>
            <td style={{ padding: "5px 6px" }}>requires <code style={{ fontFamily: "ui-monospace, monospace", fontSize: 11, background: "#24143012", padding: "1px 4px", borderRadius: 3 }}>{requiredProp}</code></td>
            <td style={{ padding: "5px 6px", fontWeight: 700, color: satisfied ? "#241430" : "#E8A020" }}>{satisfied ? "satisfied" : "missing"}</td>
          </tr>
        </tbody>
      </table>
      {satisfied
        ? <div style={{ padding: 12, borderRadius: 8, textAlign: "center", fontWeight: 600, background: accent }}>renders</div>
        : <div style={{ padding: 12, borderRadius: 8, textAlign: "center", fontWeight: 600, border: "2px dashed #E8A020", color: "#E8A020", background: "#E8A02012" }}>contract broken</div>}
    </div>
  );
}
